        event.preventDefault();
        setKeyword(event.target.value);

    }
    return (
        <div>
            <form onSubmit={handleResponse}>
<input type="Search" onChange={StoreKweyword}placeholder="Type a word"></input>
<button type="submit">Search</button>
            </form>
        </div>
    )
}
